using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and software systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including calculus, algebra, and statistics." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events, civilizations, and historical analysis." },
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Leading researcher in algorithm design with 15 years of teaching experience. Published over 40 papers on computational theory and formal methods.", Email = "alovelace@university.edu", OfficeHours = "Mon/Wed 2:00–4:00 PM" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Specializes in artificial intelligence and machine learning. Recipient of the Distinguished Teaching Award in 2024.", Email = "aturing@university.edu", OfficeHours = "Tue/Thu 1:00–3:00 PM" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Expert in abstract algebra and theoretical physics. Has authored three widely-used textbooks on modern algebra.", Email = "enoether@university.edu", OfficeHours = "Mon/Wed 10:00 AM–12:00 PM" },
            new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Professor", Bio = "Renowned physicist and educator known for making complex topics accessible. Research focus on quantum electrodynamics.", Email = "rfeynman@university.edu", OfficeHours = "Tue/Thu 3:00–5:00 PM" },
            new() { Id = 5, Name = "Dr. Virginia Woolf", Title = "Associate Professor", Bio = "Scholar of modernist literature and creative writing. Leads the university's annual literary symposium.", Email = "vwoolf@university.edu", OfficeHours = "Mon/Fri 1:00–3:00 PM" },
            new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Professor", Bio = "Historian specializing in social movements and American history. Author of several acclaimed works on civil rights.", Email = "hzinn@university.edu", OfficeHours = "Wed/Fri 10:00 AM–12:00 PM" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering the fundamentals of programming, problem solving, and computational thinking. Students will learn Python and explore topics including variables, control flow, functions, and basic data structures. No prior programming experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, Instructor = instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Emphasizes time and space complexity analysis. Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", DepartmentId = 1, Instructor = instructors[1], IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Introduction to relational database design, SQL, normalization, indexing, and query optimization. Includes a semester-long project building a complete database-backed application. Prerequisites: CS 201.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Building 110", DepartmentId = 1, Instructor = instructors[0] },
            new() { Id = 4, Code = "CS 450", Title = "Machine Learning", Description = "Survey of machine learning methods including supervised learning, unsupervised learning, and reinforcement learning. Covers neural networks, decision trees, SVMs, and practical applications using Python. Prerequisites: CS 201, MATH 202.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Tech Building 215", DepartmentId = 1, Instructor = instructors[1], IsFeatured = true },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Emphasis on problem-solving and mathematical reasoning.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 101", DepartmentId = 2, Instructor = instructors[2] },
            new() { Id = 6, Code = "MATH 202", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications in computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Math Building 203", DepartmentId = 2, Instructor = instructors[2], IsFeatured = true },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian methods. Includes practical labs using R.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Room = "Math Building 105", DepartmentId = 2, Instructor = instructors[2] },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments. Corequisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Physics Lab 100", DepartmentId = 3, Instructor = instructors[3], IsFeatured = true },
            new() { Id = 9, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continues the laboratory experience from Physics I. Prerequisites: PHYS 101, MATH 101.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Physics Lab 100", DepartmentId = 3, Instructor = instructors[3] },
            new() { Id = 10, Code = "ENG 101", Title = "College Writing", Description = "Develop skills in academic writing, critical reading, and argumentation. Students produce multiple essays and a research paper. Emphasis on revision and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Humanities 301", DepartmentId = 4, Instructor = instructors[4] },
            new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Covers major authors, literary movements, and cultural contexts. Includes class discussions and analytical essays.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 205", DepartmentId = 4, Instructor = instructors[4], IsFeatured = true },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to 1500 CE. Examines political, social, economic, and cultural developments across Africa, Asia, Europe, and the Americas.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Room = "Humanities 110", DepartmentId = 5, Instructor = instructors[5] },
            new() { Id = 13, Code = "HIST 220", Title = "Modern American History", Description = "American history from the Civil War to the present. Topics include industrialization, civil rights, the Cold War, and contemporary issues. Uses primary sources and historiographical debate.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Humanities 110", DepartmentId = 5, Instructor = instructors[5] },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.ToList();
    }
}

