@page "/"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Browse departments, explore courses, and submit your enrollment request.</p>

<hr />

<h2>Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">@course.Code</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                    <p class="card-text">
                        <small class="text-muted">
                            <strong>@course.Credits credits</strong> · @course.Instructor.Name
                        </small>
                    </p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    <a href="enroll?courseId=@course.Id" class="btn btn-outline-secondary btn-sm">Enroll</a>
                </div>
            </div>
        </div>
    }
</div>

<h2>Departments</h2>
<div class="row row-cols-1 row-cols-md-2 g-3 mb-4">
    @foreach (var dept in departments)
    {
        var courseCount = Catalog.GetCoursesByDepartment(dept.Id).Count;
        <div class="col">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name (@dept.Code)</h5>
                    <p class="card-text">@dept.Description</p>
                    <a href="courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">
                        Browse @courseCount course@(courseCount != 1 ? "s" : "")
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>
<p>Search and filter the course catalog to find the right courses for you.</p>

<div class="card mb-4">
    <div class="card-body">
        <div class="row g-3">
            <div class="col-md-5">
                <label for="searchInput" class="form-label">Search</label>
                <input id="searchInput" type="text" class="form-control" placeholder="Course name, code, or instructor…"
                       @bind="searchTerm" @bind:event="oninput" />
            </div>
            <div class="col-md-3">
                <label for="deptFilter" class="form-label">Department</label>
                <select id="deptFilter" class="form-select" @bind="selectedDepartmentId">
                    <option value="0">All Departments</option>
                    @foreach (var dept in departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="creditFilter" class="form-label">Credits</label>
                <select id="creditFilter" class="form-select" @bind="selectedCredits">
                    <option value="0">Any</option>
                    <option value="3">3 credits</option>
                    <option value="4">4 credits</option>
                </select>
            </div>
            <div class="col-md-2 d-flex align-items-end">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
            </div>
        </div>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted mb-3">Showing @filteredCourses.Count course@(filteredCourses.Count != 1 ? "s" : "")</p>

    <div class="table-responsive">
        <table class="table table-hover">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td><small>@course.Schedule</small></td>
                        <td>@course.Instructor.Name</td>
                        <td>
                            <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = "";
    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int _selectedDepartmentId;
    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    private int _selectedCredits;
    private int selectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();

        // Check for departmentId in query string (from homepage links)
        var uri = Nav.ToAbsoluteUri(Nav.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query)
                .TryGetValue("departmentId", out var deptIdValue) &&
            int.TryParse(deptIdValue, out var deptId))
        {
            _selectedDepartmentId = deptId;
        }

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = Catalog.SearchCourses(
            _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null,
            _selectedCredits > 0 ? _selectedCredits : null);
    }

    private void ClearFilters()
    {
        _searchTerm = "";
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }
}

