@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>
<p>Search and filter the course catalog to find the right courses for you.</p>

<div class="card mb-4">
    <div class="card-body">
        <div class="row g-3">
            <div class="col-md-5">
                <label for="searchInput" class="form-label">Search</label>
                <input id="searchInput" type="text" class="form-control" placeholder="Course name, code, or instructor…"
                       @bind="searchTerm" @bind:event="oninput" />
            </div>
            <div class="col-md-3">
                <label for="deptFilter" class="form-label">Department</label>
                <select id="deptFilter" class="form-select" @bind="selectedDepartmentId">
                    <option value="0">All Departments</option>
                    @foreach (var dept in departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="creditFilter" class="form-label">Credits</label>
                <select id="creditFilter" class="form-select" @bind="selectedCredits">
                    <option value="0">Any</option>
                    <option value="3">3 credits</option>
                    <option value="4">4 credits</option>
                </select>
            </div>
            <div class="col-md-2 d-flex align-items-end">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
            </div>
        </div>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted mb-3">Showing @filteredCourses.Count course@(filteredCourses.Count != 1 ? "s" : "")</p>

    <div class="table-responsive">
        <table class="table table-hover">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td><small>@course.Schedule</small></td>
                        <td>@course.Instructor.Name</td>
                        <td>
                            <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = "";
    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int _selectedDepartmentId;
    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    private int _selectedCredits;
    private int selectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();

        // Check for departmentId in query string (from homepage links)
        var uri = Nav.ToAbsoluteUri(Nav.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query)
                .TryGetValue("departmentId", out var deptIdValue) &&
            int.TryParse(deptIdValue, out var deptId))
        {
            _selectedDepartmentId = deptId;
        }

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = Catalog.SearchCourses(
            _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null,
            _selectedCredits > 0 ? _selectedCredits : null);
    }

    private void ClearFilters()
    {
        _searchTerm = "";
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using Microsoft.AspNetCore.Components.Forms
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Complete the form below to request enrollment in a course. You will receive a confirmation by email.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0">A confirmation will be sent to <strong>@Model.Email</strong>.
            You can expect to hear back within 2–3 business days.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-lg-7">
            <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
                    <ValidationMessage For="() => Model.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId"
                               placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => Model.StudentId" />
                    <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address</label>
                    <InputText id="email" class="form-control" type="email" @bind-Value="Model.Email" />
                    <ValidationMessage For="() => Model.Email" />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="Model.Comments" />
                    <ValidationMessage For="() => Model.Comments" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} – {course.Title}" : "Unknown";
        submitted = true;
    }
}

